// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, uint256 warpTime) public {
        // keep the timestamp in a wide admissible domain, strictly past pastBlockTime (0)
        warpTime = bound(warpTime, 1, type(uint256).max / 2);
        vm.warp(warpTime);

        vm.deal(address(this), amount);

        // drive the fallback entry via low-level call with empty calldata
        (bool ok, ) = address(c).call{value: amount}("");

        // General rule: a fallback call succeeds if and only if msg.value == 10 ether.
        assertTrue(ok == (amount == 10 ether), "fallback accept/reject rule violated");
    }
}
